    ["l_aubergine_marine"] = {
        ["name"] = "l_aubergine_marine",
        ["label"] = "L'Aubergine Marine",
        ["useable"] = false,
        ["weight"] = 200,
        ["type"] = "fish",
        ["fish_generation"] = "classic",
        ["description"] = "Cà tím biển là một sinh vật hấp dẫn của độ sâu đại dương. Với cái miệng rộng, nó giống như một con bò biển gặm cỏ dưới đáy biển, ăn những chất dinh dưỡng phong phú mà nó tìm thấy dưới biển. Đôi mắt màu vàng của nó mang lại cho nó tầm nhìn đặc biệt trong vực thẳm, giúp nó phát hiện những khu vực giàu thức ăn. Loại hải sâm này có một đặc điểm độc đáo: khi tiêu thụ với liều lượng cao, các thành phần hóa học của nó có thể gây ảo giác nhẹ cho người ăn. Đặc điểm này khiến nó trở thành sự tò mò trong thế giới biển và một số nền văn hóa ven biển đôi khi sử dụng nó cho mục đích nghi lễ hoặc y học. Cà tím biển là hiện thân của sự đa dạng tuyệt vời của đời sống dưới nước, với hành vi chăn thả yên bình và những đặc tính hấp dẫn. Ông vừa là nguồn mê hoặc đối với các nhà nghiên cứu biển, vừa là một huyền thoại huyền bí đối với những ai đi ngang qua con đường của ông.",
        ["illustrator"] = ".L'Atelier d'Adrien",
        ["fishing_area"] = {"littoral", "canals"},
        ["fishing_weather"] = {"CLEAR", "CLEARING", "EXTRASUNNY", "OVERCAST", "CLOUDS"},
